// Statusbar — Gtk.Statusbar
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles statusbar with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface StatusbarProps extends WidgetProps {
  className?: string
  children?: ReactNode

}

export function Statusbar({ className, children }: StatusbarProps) {
  return (
    <div className={cn("py-1.5", "px-2.5", className)}>
      {children}
    </div>
  )
}
